mapper.select:
select

from permission


        and identity like concat('%', #{identity}, '%')


        and name like concat('%', #{name}, '%')


        and parent_id = #{parentId}


        and type = #{type}


        and is_system = #{isSystem}


        and is_disabled = #{isDisabled}


order by id asc

select count(1)
from permission
where parent_id = #{parentId}

select count(1)
from role_permission_list
where permission_list_id = #{permissionId}

mapper.update:
update permission
update_time = #{updateTime}, is_disabled = #{isDisabled}, identity = #{identity}, name = #{name}, parent_id = #{parentId}, type = #{type}, is_system = #{isSystem}
where id = #{id}
